// ==============================================================================
// Migo AI Solution - chat-widget.js
// الواجهة العائمة لشات المتجر (مساعد Migo). الردود بتيجي من خدمة Deno
// (api.ts) اللي بتكلّم Gemini بمفتاح محفوظ على السيرفر - مش هنا في المتصفح.
// ==============================================================================
(function () {
  var API = 'https://migoai-72.naroelwakel-dot.deno.net/chat';
  var WA = 'https://wa.me/201060934020';
  var history = [];
  var REPLY_TIMEOUT_MS = 45000;   // أقصى وقت نستنى فيه رد السيرفر (السيرفر بيجرّب كذا مزوّد، فممكن ياخد لحد ~42 ثانية)
  var NOTE_EVERY_MS = 30000;      // كل قد إيه يظهر تنبيه جديد فوق أيقونة الشات
  var NOTE_SHOW_MS = 2500;        // مدة ظهور التنبيه قبل ما يختفي (ثانيتين ونص)

  // تنبيهات الذكر والصلاة اللي بتظهر صغيرة فوق أيقونة الشات (مش جوّه المحادثة). عدّل الكلمات من هنا.
  var NOTES = [
    'اذكر الله، تطمئن القلوب 🤍',
    'اللهم صلِّ وسلّم على نبينا محمد ﷺ',
    'هل صليت اليوم؟ متأجّلش الصلاة',
    'سبحان الله وبحمده، سبحان الله العظيم',
    'لا تنسَ أذكار الصباح والمساء',
    'أستغفر الله العظيم وأتوب إليه',
    'تبسّم، فتبسّمك في وجه أخيك صدقة',
    'الحمد لله على كل حال'
  ];

  function el(tag, cls, txt) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (txt != null) e.textContent = txt;
    return e;
  }

  // شعار أيقونة الشات: صورة دائرية. الإطار النابض حولها جاي من CSS على الزر (.migo-chat__btn)
  var LOGO_SRC = 'data:image/png;base64,';
  function logoImg(p) {
    var src = (p && p.avatar) || LOGO_SRC;
    var tf = (p && p.t) ? ';transform:' + p.t : '';   // تعديل بسيط لضبط الصورة جوه الدايرة
    return '<img class="migo-chat__logo" src="' + src + '" alt="Migo AI Solution" ' +
      'style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block' + tf + '" />';
  }

  // شخصيات الشات: الزائر ياخد شخصية واحدة تفضل معاه (بنحفظ اختياره في المتصفح)،
  // وكل شخصية ليها اسم وصورة وترحيب. صورة "عمر" هي الصورة الحالية، والتلاتة التانية مولّدة.
  // ملاحظة: الـ id لازم يطابق المفاتيح في api.ts (PERSONAS).
  var PERSONAS = [
    { id: 'omar', name: 'عمر', avatar: LOGO_SRC, t: 'scale(1.16) translateX(6%)',
      greet: 'أهلاً! 👋 أنا عمر من فريق Migo AI. اسألني عن أي سعر أو خدمة.' },
    { id: 'karim', name: 'كريم', avatar: 'https://cdn-public.eesel.ai/074824bf-1845-4f1a-84b0-bee6be6e26c4/d4192abd-748b-421a-b849-2768da08e88e/ea36d1a1e873470282608cc1d4491dfb.webp',
      greet: 'هاي! 👋 كريم معاك من Migo AI. اطلب أي سعر أو خدمة وأنا معاك.' },
    { id: 'mirna', name: 'ميرنا', avatar: 'https://cdn-public.eesel.ai/074824bf-1845-4f1a-84b0-bee6be6e26c4/d4192abd-748b-421a-b849-2768da08e88e/56f37bb0272c42cd854e8574bda31747.webp',
      greet: 'أهلاً بيك! 👋 أنا ميرنا من فريق Migo AI، أقدر أساعدك في إيه؟' },
    { id: 'habiba', name: 'حبيبة', avatar: 'https://cdn-public.eesel.ai/074824bf-1845-4f1a-84b0-bee6be6e26c4/d4192abd-748b-421a-b849-2768da08e88e/1612572bc8ea4e3eba8ca4ee8b1de9dd.webp',
      greet: 'يا هلا! 👋 حبيبة معاك من Migo AI، قولّي محتاج إيه.' }
  ];
  var PERSONA_KEY = 'migo_chat_persona';
  function pickPersona() {
    var saved = null;
    try { saved = localStorage.getItem(PERSONA_KEY); } catch (e) {}
    for (var i = 0; i < PERSONAS.length; i++) {
      if (saved && PERSONAS[i].id === saved) return PERSONAS[i];
    }
    var p = PERSONAS[Math.floor(Math.random() * PERSONAS.length)];
    try { localStorage.setItem(PERSONA_KEY, p.id); } catch (e) {}
    return p;
  }

  // تنبيه صغير فوق أيقونة الشات: جملة تظهر ثانيتين ونص وتختفي بتلاشي ناعم، وتتكرر كل فترة.
  // بيتوقف وهو مفتوح (isPanelOpen) عشان مايزحمش المحادثة.
  function startNotes(node, isPanelOpen) {
    if (!node || !NOTES.length) return;
    var i = 0;
    var showing = false;
    function show() {
      if (showing || (isPanelOpen && isPanelOpen())) return;
      showing = true;
      node.textContent = NOTES[i % NOTES.length];
      i++;
      node.classList.add('is-in');
      setTimeout(function () {
        node.classList.remove('is-in');
        setTimeout(function () { showing = false; }, 450);
      }, NOTE_SHOW_MS);
    }
    setTimeout(show, 5000);           // أول تنبيه بعد ثواني من فتح الصفحة
    setInterval(show, NOTE_EVERY_MS);
  }

  function build() {
    if (document.getElementById('migoChat')) return;
    var persona = pickPersona();
    var root = el('div', 'migo-chat');
    root.id = 'migoChat';
    root.innerHTML =
      '<button class="migo-chat__btn" type="button" aria-label="اسأل ' + persona.name + ' مساعد ميجو" style="overflow:hidden">' + logoImg(persona) + '</button>' +
      '<div class="migo-chat__note" role="status" aria-live="polite"></div>' +
      '<div class="migo-chat__panel" hidden>' +
        '<div class="migo-chat__head"><span>' + persona.name + ' · مساعد Migo</span>' +
          '<button class="migo-chat__x" type="button" aria-label="إغلاق المحادثة">إغلاق <b>✕</b></button></div>' +
        '<div class="migo-chat__body"></div>' +
        '<form class="migo-chat__form">' +
          '<input class="migo-chat__in" type="text" placeholder="اسأل عن أي سعر أو خدمة..." autocomplete="off" maxlength="400" />' +
          '<button type="submit">إرسال</button>' +
        '</form>' +
      '</div>';
    document.body.appendChild(root);

    var panel = root.querySelector('.migo-chat__panel');
    var bodyEl = root.querySelector('.migo-chat__body');
    var input = root.querySelector('.migo-chat__in');
    var form = root.querySelector('.migo-chat__form');
    var fab = root.querySelector('.migo-chat__btn');
    var note = root.querySelector('.migo-chat__note');

    function bubble(text, who) {
      var b = el('div', 'migo-chat__msg migo-chat__msg--' + who, text);
      bodyEl.appendChild(b);
      bodyEl.scrollTop = bodyEl.scrollHeight;
      return b;
    }

    bubble(persona.greet, 'bot');
    startNotes(note, function () { return !panel.hidden; });

    fab.addEventListener('click', function () {
      panel.hidden = false;
      fab.style.display = 'none';
      note.classList.remove('is-in');
      input.focus();
    });
    root.querySelector('.migo-chat__x').addEventListener('click', function () {
      panel.hidden = true;
      fab.style.display = '';
    });

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      var t = input.value.trim();
      if (!t) return;
      input.value = '';
      bubble(t, 'me');
      var past = history.slice(-6);
      history.push({ role: 'user', text: t });
      var pending = bubble('...', 'bot');
      var settled = false;
      var ctrl = (typeof AbortController !== 'undefined') ? new AbortController() : null;

      // مؤقت أمان: مهما حصل، البابل مش هيفضل "..." للأبد.
      var guard = setTimeout(function () {
        if (settled) return;
        settled = true;
        if (ctrl) ctrl.abort();
        pending.textContent = 'الرد بيتأخر شوية. جرّب تسأل تاني، أو كلّمنا على واتساب ونساعدك فورًا: ' + WA;
        bodyEl.scrollTop = bodyEl.scrollHeight;
      }, REPLY_TIMEOUT_MS);

      fetch(API, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: t, history: past, persona: persona.id }),
        signal: ctrl ? ctrl.signal : undefined
      })
        .then(function (r) { return r.json(); })
        .then(function (d) {
          if (settled) return;
          settled = true;
          clearTimeout(guard);
          var reply = d && d.reply ? d.reply : 'معلش حصلت مشكلة، جرّب تاني أو كلّمنا واتساب.';
          pending.textContent = reply;
          bodyEl.scrollTop = bodyEl.scrollHeight;
          history.push({ role: 'model', text: reply });
        })
        .catch(function () {
          if (settled) return;
          settled = true;
          clearTimeout(guard);
          pending.textContent = 'معلش فيه مشكلة في الاتصال دلوقتي. كلّمنا على واتساب: ' + WA;
          bodyEl.scrollTop = bodyEl.scrollHeight;
        });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', build);
  } else {
    build();
  }
})();
